{"query":"

query ConsumerSearchGeoQuery($geoSupportedSlug: String!, $by_prop_type: [String])
{
  geo(slug_id: $geoSupportedSlug) {
    parents {
      geo_type
      slug_id
      name
    }
    geo_statistics(group_by: property_type) {
      housing_market {
        by_prop_type(type: $by_prop_type){
          type
           attributes{
            median_listing_price
            median_lot_size
            median_sold_price
            median_price_per_sqft
            median_days_on_market
          }
        }
        listing_count
        median_listing_price
        median_rent_price
        median_price_per_sqft
        median_days_on_market
        median_sold_price
        month_to_month {
          active_listing_count_percent_change
          median_days_on_market_percent_change
          median_listing_price_percent_change
          median_listing_price_sqft_percent_change
        }
      }
    }
    recommended_cities: recommended(query: {geo_search_type: city, limit: 20}) {
      geos {
        ... on City {
          city
          state_code
          geo_type
          slug_id
        }
        geo_statistics(group_by: property_type) {
          housing_market {
            by_prop_type(type: ["home"]) {
              type
              attributes {
                median_listing_price
              }
            }
            median_listing_price
          }
        }
      }
    }
    recommended_neighborhoods: recommended(query: {geo_search_type: neighborhood, limit: 20}) {
      geos {
        ... on Neighborhood {
          neighborhood
          city
          state_code
          geo_type
          slug_id
        }
        geo_statistics(group_by: property_type) {
          housing_market {
            by_prop_type(type: ["home"]) {
              type
              attributes {
                median_listing_price
              }
            }
            median_listing_price
          }
        }
      }
    }
    recommended_counties: recommended(query: {geo_search_type: county, limit: 20}) {
      geos {
        ... on HomeCounty {
          county
          state_code
          geo_type
          slug_id
        }
        geo_statistics(group_by: property_type) {
          housing_market {
            by_prop_type(type: ["home"]) {
              type
              attributes {
                median_listing_price
              }
            }
            median_listing_price
          }
        }
      }
    }
    recommended_zips: recommended(query: {geo_search_type: postal_code, limit: 20}) {
      geos {
        ... on PostalCode {
          postal_code
          geo_type
          slug_id
        }
        geo_statistics(group_by: property_type) {
          housing_market {
            by_prop_type(type: ["home"]) {
              type
              attributes {
                median_listing_price
              }
            }
            median_listing_price
          }
        }
      }
    }
  }
}","variables":{"geoSupportedSlug":"Miami_FL","by_prop_type":["home"]},"operationName":"ConsumerSearchGeoQuery","callfrom":"SRP","nrQueryType":"GEO_SRP","cacheKey":"GEO_SRP","cacheParams":"/geo-srp/Miami_FL","isClient":true}

