query ConsumerSearchQuery($query: HomeSearchCriteria!) {
  rich_snippets: home_search(query: $query,
    sort:{field: home_phrases_score, direction: desc},
    limit: 20,
  ){
    count
    total
    results {
      property_id
      list_price
      description {
        beds
        baths
        baths_full
        baths_half
        baths_3qtr
        sqft
      }
      primary_photo(https: true) {
        href
      }
      permalink
      href
      flags {
        is_pending
        is_foreclosure
        is_contingent
        is_new_construction
        is_new_listing (days: 14)
        is_price_reduced (days: 30)
        is_plan
      }
      location {
        address {
          city
          country
          line
          postal_code
          state_code
          state
        }
      }
      open_houses {
        start_date
        end_date
      }
      sentences_list: highlights(highlight_type: phrase_srp_spl_homes) {
        ... on HighlightPhrase {
          phrase
          text
        }
      }
    }
  }
}","callfrom":"SRP","nrQueryType":"SPECIAL_FEATURES","cacheKey":"SPECIAL_FEATURES","cacheParams":"/special_features/Miami_FL","variables":{"query":{"search_location":{"location":"Miami, FL"},"status":"for_sale"}},"isClient":true}

{"query":"
fragment SchoolListData on SchoolList {
  schools {
    id
    name
    slug_id
    rating
    location {
      city
      state
      city_slug_id
    }
  }
  total
}

query ConsumerSearchQuery($elementary: SchoolSearchCriteria!, $middle: SchoolSearchCriteria!, $high: SchoolSearchCriteria!, $private: SchoolSearchCriteria!, $district: SchoolDistrictSearchCriteria!, $university: PoiCriteria!) {
  elementary: school_search(query: $elementary, limit: 9, sort: [ratingDesc, studentCountDesc]) {
    ...SchoolListData
  }
  middle: school_search(query: $middle, limit: 9, sort: [ratingDesc, studentCountDesc]) {
    ...SchoolListData
  }
  high: school_search(query: $high, limit: 9, sort: [ratingDesc, studentCountDesc]) {
    ...SchoolListData
  }
  private: school_search(query: $private, limit: 9, sort: [ratingDesc, studentCountDesc]) {
    ...SchoolListData
  }
  university: pois(query: $university, limit: 9) {
    lid
    name
    slug_id
    city
    city_slug_id
    city
    state_code
  }
  district: school_district_search(query: $district, limit: 9){
    districts {
      id
      name
      rating
      location {
        city
        state
        city_slug_id
      }
    }
    total
  }
}
","variables":{"elementary":{"education_level":"elementary","city":"Miami","state_code":"FL"},"middle":{"education_level":"middle","city":"Miami","state_code":"FL"},"high":{"education_level":"high","city":"Miami","state_code":"FL"},"district":{"city":"Miami","state_code":"FL"},"private":{"education_level":"private","city":"Miami","state_code":"FL"},"university":{"slug_id":"Miami_FL","categories":"university"}},"callfrom":"SRP","nrQueryType":"SCHOOLS","cacheKey":"SCHOOLS","cacheParams":"/schools/v2/Miami_FL","isClient":true}

